 InputSystem.QueueStateEvent(keys,new KeyboardState(m.PeekKey(0)));yield return Frames();Check(Visible(0),"private hand visible before pause test");m.Pause();Check(Hidden(),"pause immediately clears every private display");int hand=m.Table.HandNumber,actor=m.Table.Actor,pot=m.Table.Pot;yield return new WaitForSecondsRealtime(.12f);Check(m.Table.HandNumber==hand&&m.Table.Actor==actor&&m.Table.Pot==pot,"pause preserves authoritative hand, actor and pot");m.Resume();yield return Frames();Check(Hidden(),"held peek through resume cannot reveal without release");Neutral();yield return Frames();InputSystem.QueueStateEvent(keys,new KeyboardState(m.PeekKey(0)));yield return Frames();Check(Visible(0),"fresh peek after resume restores only own hand");InputSystem.RemoveDevice(whole);whole=null;yield return Frames();Check(m.Paused&&m.menus.Screen==SportsEventScreen.Join&&Hidden(),"actual software source removal hides hands and requires reconnect");replacement=InputSystem.AddDevice<Gamepad>();Check(m.Assign(1,replacement),"explicit replacement retains seat ownership");Neutral();yield return Frames();m.Resume();yield return Frames();Check(m.Live&&m.Table.HandNumber==hand&&m.Table.Actor==actor&&m.Table.Pot==pot,"replacement resumes exact existing hand");whole=replacement;replacement=null;
