 void Capture(int width,int height,string tag){var canvas=m.menus.GetComponent<Canvas>();var mode=canvas.renderMode;var worldCamera=canvas.worldCamera;float distance=canvas.planeDistance,scale=canvas.scaleFactor;var scaler=canvas.GetComponent<CanvasScaler>();bool scaling=scaler.enabled;var transforms=canvas.GetComponentsInChildren<Transform>(true);var layers=transforms.Select(t=>t.gameObject.layer).ToArray();var active=RenderTexture.active;var rt=RenderTexture.GetTemporary(width,height,24,RenderTextureFormat.ARGB32);var ui=new GameObject("Owned temporary UI render camera").AddComponent<Camera>();ui.cullingMask=1<<5;ui.clearFlags=CameraClearFlags.SolidColor;ui.backgroundColor=Color.clear;ui.transform.position=new Vector3(0,1000,-1000);ui.orthographic=true;ui.nearClipPlane=.1f;ui.farClipPlane=50;ui.targetTexture=rt;try{for(int i=0;i<transforms.Length;i++)transforms[i].gameObject.layer=5;scaler.enabled=false;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=ui;canvas.planeDistance=10;canvas.scaleFactor=Mathf.Min(width/1920f,height/1080f);Canvas.ForceUpdateCanvases();foreach(var camera in m.cameras){var old=camera.targetTexture;float aspect=camera.aspect;camera.targetTexture=rt;camera.aspect=width*camera.rect.width/(height*camera.rect.height);camera.Render();camera.targetTexture=old;camera.aspect=aspect;}RenderTexture.active=rt;var world=new Texture2D(width,height,TextureFormat.RGBA32,false);world.ReadPixels(new Rect(0,0,width,height),0,0);world.Apply();ui.Render();var corners=new Vector3[4];for(int view=0;view<m.HumanViews;view++){var r=m.seats[view].view.rect;bool inside=true;foreach(var card in m.presentation.panes[view].board.Concat(m.presentation.panes[view].own)){if(!card.gameObject.activeInHierarchy)continue;card.GetComponent<RectTransform>().GetWorldCorners(corners);foreach(var corner in corners){var point=ui.WorldToViewportPoint(corner);inside&=point.x>=r.xMin-.002f&&point.x<=r.xMax+.002f&&point.y>=r.yMin-.002f&&point.y<=r.yMax+.002f;}}Check(inside,"all visible public/private cards stay in own viewport "+tag+" "+width+"x"+height+" view="+view);}RenderTexture.active=rt;var image=new Texture2D(width,height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();var foreground=image.GetPixels32();var backgroundPixels=world.GetPixels32();for(int px=0;px<foreground.Length;px++){float alpha=foreground[px].a/255f;backgroundPixels[px]=Color32.Lerp(backgroundPixels[px],foreground[px],alpha);}image.SetPixels32(backgroundPixels);image.Apply();Destroy(world);File.WriteAllBytes(folder+"/"+tag+"-"+width+"x"+height+"-controlled-ui.png",image.EncodeToPNG());Destroy(image);}finally{canvas.renderMode=mode;canvas.worldCamera=worldCamera;canvas.planeDistance=distance;canvas.scaleFactor=scale;scaler.enabled=scaling;for(int i=0;i<transforms.Length;i++)transforms[i].gameObject.layer=layers[i];RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);Destroy(ui.gameObject);}}
